            "description": "Entrada & Imersão Auditiva • Anna's Decision: Acompanhe a história pelos ouvidos sem traduzir na cabeça.",
            "videoUrl": "https://firebasestorage.googleapis.com/v0/b/agoraeufalo-3463a.firebasestorage.app/o/courses%2Fmagic-stories-legacy%2FMS007%2FMS007_LR_1.mp4?alt=media",
            "audioUrl": "https://firebasestorage.googleapis.com/v0/b/agoraeufalo-3463a.firebasestorage.app/o/courses%2Fms-legacy%2FMS007%2Faudio_ms007_lr.mp3?alt=media",
