            "order": 1,
            "duration": "38:45",
            "description": "Entrada & Imersão Auditiva Completa • A história de Carlos, administrador de empresas em Belo Horizonte que decide dominar o inglês para ser promovido e viajar para os EUA.",
            "videoUrl": "https://firebasestorage.googleapis.com/v0/b/agoraeufalo-3463a.firebasestorage.app/o/courses%2Fmagic-stories-legacy%2FMS010%2FMS010_LR_1.mp4?alt=media",
            "audioUrl": "https://firebasestorage.googleapis.com/v0/b/agoraeufalo-3463a.firebasestorage.app/o/courses%2Fms-legacy%2FMS010%2Faudio_ms010_lr_1.mp3?alt=media",
            "thumbnailUrl": "assets/images/thumbs/ms010/thumb_ms010_lr_1.jpg",
